// The "storage" module hasn't been migrated to the emi compiler yet (see
// modules/storage/StorageModule3.yml), so there's no generated Dto to replace the old
// "Generated by fireback 1.3.2" FileEntity class with. Every real consumer only ever
// used it as a plain type (mock data shaping, upload-widget prop types) - never
// .Fields/.Navigation/any data-fetching hook - so a plain type mirroring its old
// field list is all that's actually needed here.
export interface FileVariations {
  name?: string | null;
}

export interface FileEntity {
  uniqueId?: string | null;
  name?: string | null;
  // For each upload, we need to assign a operation id, so if the operation has been
  // cancelled, it would be cleared automatically, and there won't be orphant files
  // in the database.
  operationId?: string | null;
  diskPath?: string | null;
  size?: number | null;
  virtualPath?: string | null;
  type?: string | null;
  variations?: FileVariations[] | null;
}
